import{_ as n,c as t,o,ag as i}from"./chunks/framework.Bzez9NG9.js";const a="/space/img/connections.png",s="/space/img/connection-actions.png",m=JSON.parse('{"title":"Connections","description":"Configure and manage SPACE connections to IBM Planning Analytics and supported external data sources such as Google BigQuery.","frontmatter":{"title":"Connections","description":"Configure and manage SPACE connections to IBM Planning Analytics and supported external data sources such as Google BigQuery.","keywords":["connections","IBM Planning Analytics","TM1","Google BigQuery","environment type","connection access","security roles"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/connections/index.md","filePath":"doc/configuration/connections/index.md"}'),c={name:"doc/configuration/connections/index.md"};function r(l,e,d,p,h,u){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="connections" tabindex="-1">Connections <a class="header-anchor" href="#connections" aria-label="Permalink to &quot;Connections&quot;">​</a></h1><p>Connections define the external systems and data environments that SPACE can access.</p><p>A single SPACE instance can contain multiple connections, including IBM Planning Analytics environments and supported external data sources such as Google BigQuery. Connections can be reused across SPACE features, including SPACE AI, according to the access granted to the user or role.</p><p><img src="'+a+'" alt="Connections list" data-zoomable=""></p><p>From the Connections page you can create, edit, duplicate, control access to, or remove connections.</p><h2 id="connection-types" tabindex="-1">Connection types <a class="header-anchor" href="#connection-types" aria-label="Permalink to &quot;Connection types&quot;">​</a></h2><p>When creating a connection, select the <strong>Connection Type</strong> that matches the source system.</p><p>SPACE supports connection-specific configuration for:</p><ul><li><a href="./ibm-planning-analytics.html">IBM Planning Analytics</a></li><li><a href="./bigquery.html">Google BigQuery</a></li></ul><p>Each connection type has its own connection and authentication settings.</p><h2 id="environment-type" tabindex="-1">Environment type <a class="header-anchor" href="#environment-type" aria-label="Permalink to &quot;Environment type&quot;">​</a></h2><p><strong>Environment Type</strong> is a descriptive label used to classify a connection as:</p><ul><li>Production</li><li>UAT</li><li>QA</li><li>Development</li><li>Sandbox</li></ul><p>The environment type does not change how SPACE authenticates to or communicates with the source system.</p><p>It helps users distinguish environments and provides useful context when connections are referenced throughout SPACE, including in SPACE AI.</p><h2 id="creating-or-editing-a-connection" tabindex="-1">Creating or editing a connection <a class="header-anchor" href="#creating-or-editing-a-connection" aria-label="Permalink to &quot;Creating or editing a connection&quot;">​</a></h2><p>Choose <strong>New connection</strong>, or open an existing connection, to configure it.</p><p>Common settings include:</p><ul><li><strong>Connection Type</strong> – the source system, such as IBM Planning Analytics or Google BigQuery.</li><li><strong>Environment Type</strong> – descriptive classification of the environment.</li><li><strong>Name</strong> – friendly name shown throughout SPACE.</li></ul><p>Additional settings depend on the selected connection type.</p><p>See the connection-specific guides for setup and authentication:</p><ul><li><a href="./ibm-planning-analytics.html">IBM Planning Analytics</a></li><li><a href="./bigquery.html">Google BigQuery</a></li></ul><h2 id="connection-actions" tabindex="-1">Connection actions <a class="header-anchor" href="#connection-actions" aria-label="Permalink to &quot;Connection actions&quot;">​</a></h2><p>Select a connection to access actions for managing or reusing its configuration.</p><p><img src="'+s+'" alt="Connection actions" data-zoomable=""></p><h3 id="duplicate" tabindex="-1">Duplicate <a class="header-anchor" href="#duplicate" aria-label="Permalink to &quot;Duplicate&quot;">​</a></h3><p>Use <strong>Duplicate</strong> to create a new connection by reusing the settings of an existing connection.</p><p>The copied settings open in a new connection form so you can change only the values that are different. This is useful when development, test, and production environments use similar configuration.</p><h3 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h3><p>Use <strong>Access</strong> to control what SPACE security roles can do with the selected connection.</p><p>Connection access is capability-based, and the available capabilities depend on the connection type.</p><p>For IBM Planning Analytics, see <a href="./ibm-planning-analytics.html#connection-access">IBM Planning Analytics → Connection access</a>.</p><h3 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h3><p>Use <strong>Delete</strong> to remove one or more selected connections.</p><p>Confirm that a connection is no longer required by users or automated workflows before removing it.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./../access.html">Access</a> explains SPACE users, security roles, access tokens, and secrets.</li><li><a href="./../jobs.html">Jobs</a> explains scheduled tasks that can use connection-specific job credentials.</li><li><a href="./../#paw-environments">PAW environments</a> explains the personal PAW-to-SPACE mappings used by the SPACE extension. These are separate from the shared connections configured here.</li></ul>',37)]))}const f=n(c,[["render",r]]);export{m as __pageData,f as default};
